"""Write CONFIG_STUDY.md and results/config_payload.png from results/config_study.json (src/config_study.py).
Light: no BEMT runs, only arithmetic on the saved results and the hand checks."""
import json, math, os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "src"))
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from common import ROOT, RESULTS, load_params, load_catalog

o = json.load(open(os.path.join(RESULTS, "config_study.json")))
ph1 = json.load(open(os.path.join(RESULTS, "phase1.json")))
p = load_params(); cs = p["config_study"]; cat = load_catalog()
b = o["baseline"]; pt = o["pitch"]; du = o["duct"]; cx = o["coax"]
W = ph1["vehicle"]["weight_n"]; t_h = W / 3; R = ph1["vehicle"]["R"]; A = ph1["vehicle"]["disk_area"]
WHKG = p["mass"]["pack_wh_per_kg_cited"]
pct = lambda x, base: 100 * (x / base - 1)
pay = lambda wh, hw, whkg=WHKG: -(hw + (wh - b["pack_wh"]) / whkg)

# ---- hand checks computed here ----------------------------------------------------------------------------------
rho = 1.1100  # placeholder, replaced from the hover numbers below
# open rotor ideal hover power from momentum theory, back out rho from the BEMT FoM definition is circular, so use the atmosphere
sys.path.insert(0, os.path.join(ROOT, "src"))
import atmosphere as atm
hot = atm.state(p["atmospheres"][p["design_atmosphere"]]["temp_c"], p["atmospheres"][p["design_atmosphere"]]["alt_m"]); rho = hot["rho"]
p_ideal_open = 3 * t_h ** 1.5 / math.sqrt(2 * rho * A)
duct0 = next(c for c in du["cases"] if c["sigma_e"] == 1.0 and not c["tip_loss"])
duct0_tl = next(c for c in du["cases"] if c["sigma_e"] == 1.0 and c["tip_loss"])
duct11 = next(c for c in du["cases"] if c["sigma_e"] == 1.1 and not c["tip_loss"])
vd_hand = math.sqrt(1.0 * t_h / (rho * A)); mom_hand = rho * A * vd_hand * p["mission"]["cruise_speed_ms"]
# Prandtl's biplane factor: two lifting surfaces of span b at gap G share induced drag through
# sigma = (1 - 0.66 G/b) / (1.055 + 3.7 G/b) (Prandtl 1924, NACA TN 182). A rotor in edgewise flight acts like a circular wing
# of span D, so for equal loads the pair's induced power is (1 + sigma) / 2 of one disk carrying both.
G = cx["design_spacing_over_D"]
sig_bi = (1 - 0.66 * G) / (1.055 + 3.7 * G)
c_ = cx["cruise"]
ratio_overlap = (2 * c_["p_induced_isolated_rotor_w"] + c_["overlap_fraction"] * (c_["p_induced_one_disk_w"] - 2 * c_["p_induced_isolated_rotor_w"])) / c_["p_induced_one_disk_w"]
cruise_biplane = c_["isolated_w"] + 3 * (c_["p_induced_one_disk_w"] * (1 + sig_bi) / 2 - 2 * c_["p_induced_isolated_rotor_w"])
# RPM-control speed vs pitch: time for +20 % thrust (T ~ Omega^2 -> +9.5 % RPM) on the motor's spare torque
mot = cat["motors"]["tmotor_u15xl_kv38"]; kt = 60 / (2 * math.pi * mot["kv"])
om_h = b["hover_rpm"] * 2 * math.pi / 60; q_h = b["hover_w"] / 3 / om_h
i_rot = 2 * ph1["mass_budget"]["blade_kg"] * R * R / 4          # tapered blade: about m R^2 / 4 each (a uniform rod is m R^2 / 3)
dq = kt * mot["peak_current_a"] - q_h
t_rpm = i_rot * om_h * (math.sqrt(1.2) - 1) / dq

# ---- payload chart -----------------------------------------------------------------------------------------------
S = o["summary"]
fig, ax = plt.subplots(figsize=(7.5, 3.2))
for k, s in enumerate(S):
    lo, hi, est = pay(s["pack_wh_best"], s["hardware_kg"]), pay(s["pack_wh_worst"], s["hardware_kg"]), pay(s["pack_wh_estimate"], s["hardware_kg"])
    ax.plot([hi, lo], [k, k], color="#2a78d6", lw=6, alpha=0.35, solid_capstyle="butt")
    ax.plot(est, k, "o", color="#0b0b0b")
ax.set_yticks(range(len(S))); ax.set_yticklabels([s["config"] for s in S], fontsize=7); ax.invert_yaxis()
ax.axvline(0, color="#0b0b0b", lw=0.8); ax.grid(alpha=.3, axis="x")
ax.set_xlabel(f"payload change vs Phase 2 baseline [kg], {WHKG:.0f} Wh/kg pack (bar: range, dot: estimate)")
fig.tight_layout(); fig.savefig(os.path.join(RESULTS, "config_payload.png"), dpi=150); plt.close(fig)

# ---- report ------------------------------------------------------------------------------------------------------
rows = {r["d_theta_deg"]: r for r in pt["rows"] if "error" not in r}
bf, vp = pt["best_fixed"], pt["variable"]
sel = cx["selected"]; mo = cx["motor_out"]
coax_half = next(s for s in S if "half-size" in s["config"]); coax_six = next(s for s in S if "six" in s["config"])
duct_s = next(s for s in S if s["config"].startswith("Ducted")); var_s = next(s for s in S if s["config"].startswith("Variable"))
L = []
w = L.append
w("# Configuration study: pitch, duct and coaxial (Phase 5.0)\n")
w("Generated by `make_config_report.py` from `results/config_study.json` (`src/config_study.py`). Do not edit by hand.\n")
w("Question: should the 280 lb tricopter change its rotor configuration? Four options against the Phase 2 baseline (open rotor, fixed pitch,"
  " 2 blades, one per arm), all on the same blade, polars, hot-day atmosphere and 10 nmi mission as Phase 2.\n")
w("## Answer\n")
w(f"- **Pitch: no.** The Phase 2 blade already sits at the bottom of the power curve. The best fixed setting ({bf['d_theta_deg']:+.0f}°) saves"
  f" {-pct(bf['pack_wh'], b['pack_wh']):.1f} % of mission energy but drops T/W from {rows[0]['tw']:.2f} to {bf['tw']:.2f}. Variable pitch, re-set in every segment"
  f" (hover {vp['settings_deg']['hover']:+.1f}°, climb {vp['settings_deg']['climb']:+.1f}°, cruise {vp['settings_deg']['cruise']:+.1f}°), saves"
  f" {-pct(vp['pack_wh'], b['pack_wh']):.1f} % and raises T/W only to {vp['tw_max']:.2f}, because the motor is current-limited, not RPM-limited. The"
  f" {var_s['hardware_kg']:.1f} kg of pitch hubs and servos then cost {-pay(vp['pack_wh'], var_s['hardware_kg']):.1f} kg of payload. Its real value is control speed,"
  " which this study does not price (see Pitch).")
w(f"- **Duct: no, decisively.** In hover a duct cuts power by {-pct(duct0['hover_w'], b['hover_w']):.0f} %, which is what momentum theory promises. But this mission is"
  f" {100 * (1 - b['hover_energy_share']):.0f} % cruise by energy, and in cruise each duct has to turn about {duct0['momentum_drag_n_each']:.0f} N of incoming air"
  f" (momentum drag, about the same as its thrust). Cruise power rises 2–3×, the pack grows {pct(duct_s['pack_wh_best'], b['pack_wh']):.0f}–{pct(duct_s['pack_wh_worst'], b['pack_wh']):.0f} %, and the"
  f" three ducts weigh about {duct_s['hardware_kg']:.0f} kg. Payload loss: {-pay(duct_s['pack_wh_best'], duct_s['hardware_kg']):.0f}–{-pay(duct_s['pack_wh_worst'], duct_s['hardware_kg']):.0f} kg.")
same_pack_range = b["pack_wh"] / cx["pack_wh"]["overlap"] - 1
w(f"- **Coaxial pair per arm: payload-neutral, but it buys range, yaw balance and (with full-size motors) motor-out survival.** In hover the pair at"
  f" h = {G} D uses only {-pct(sel['vs_single_rotor'], 1):.1f} % less power than one rotor, because interference eats almost all of the second rotor's benefit. Cruise is"
  f" different: two disks per arm work on more air, so the estimate is {pct(c_['overlap_w'], b['cruise_w']):+.0f} % cruise power and"
  f" {pct(cx['pack_wh']['overlap'], b['pack_wh']):+.0f} % pack energy (range {pct(cx['pack_wh']['optimistic'], b['pack_wh']):+.0f} to {pct(cx['pack_wh']['pessimistic'], b['pack_wh']):+.0f} %)."
  f" Prandtl's biplane factor gives nearly the same cruise power ({cruise_biplane / 1000:.1f} kW vs {c_['overlap_w'] / 1000:.1f} kW). But a 20 % smaller pack is only"
  f" {(b['pack_wh'] - cx['pack_wh']['overlap']) / WHKG:.1f} kg of battery, and half-size motors add {coax_half['hardware_kg']:.1f} kg, so payload changes by"
  f" {pay(coax_half['pack_wh_estimate'], coax_half['hardware_kg']):+.1f} kg (range {pay(coax_half['pack_wh_worst'], coax_half['hardware_kg']):+.0f} to {pay(coax_half['pack_wh_best'], coax_half['hardware_kg']):+.0f}). What"
  f" it does buy: about {100 * same_pack_range:.0f} % more cruise range on the same pack (estimate), balanced yaw torque on every arm (no tilt servo), and,"
  f" with six U15XLs ({pay(coax_six['pack_wh_estimate'], coax_six['hardware_kg']):+.0f} kg payload), survival of a motor failure in hover: one U15XL lifts a whole"
  f" arm at T/W {mo['six_u15xl_max_thrust_over_arm_hover']:.2f}. A half-size motor cannot ({mo['half_size_max_thrust_over_arm_hover']:.2f}).")
w("- **Recommendation.** Keep the Phase 2 rotor (open, fixed pitch) for payload. Pitch and duct are closed. The coaxial arm is the one configuration"
  " change worth carrying forward, and it should be picked for range margin and redundancy, not payload. Before committing: redesign the blade"
  " for half the thrust per rotor (this study reuses the Phase 2 blade off-design), decide whether motor-out survival is a requirement, which"
  " sets half-size against full-size motors, and confirm the cruise interference with CFD (coaxial MRF case at μ ≈ 0.17), since the benefit rests"
  " on a wake model.\n")
w("![Payload change](results/config_payload.png)\n")
w("![Pitch, coaxial interference and payload](results/config_study.png)\n")
w("## Baseline (regression check)\n")
w(f"Hover {b['hover_w']:.0f} W, climb {b['climb_w']:.0f} W, cruise {b['cruise_w']:.0f} W (3 rotors, shaft), mission pack **{b['pack_wh']:.0f} Wh**,"
  f" the same as the Phase 2 final blade (7475 Wh). Hover, descent and climb carry {100 * b['hover_energy_share']:.0f} % of the energy and cruise {100 * (1 - b['hover_energy_share']):.0f} %:"
  " that split decides most of this study.\n")

w("## 1–2. Pitch\n")
w("A constant d_theta is added to the whole blade's twist (the rotor still trims thrust with RPM). Fixed pitch keeps one d_theta for the whole mission."
  " Variable pitch picks the best d_theta in each segment: a parabola fitted through the grid minimum and its neighbours. Settings that leave less"
  f" than {p['design']['min_stall_margin_deg']:.0f}° hover stall margin, or less than {cs['cruise_min_stall_margin_deg']:.0f}° anywhere on the azimuth in cruise, are not allowed.\n")
w("| d_theta [°] | Hover [W] | Cruise [W] | Pack [Wh] | T/W (U15XL, 84 V) | Hover stall margin [°] | Cruise stall margin [°] |")
w("|---|---|---|---|---|---|---|")
for d, r in sorted(rows.items()):
    w(f"| {d:+.0f} | {r['hover_w']:.0f} | {r['cruise_w']:.0f} | {r['pack_wh']:.0f} | {r['tw']:.2f} | {r['stall_margin_hover_deg']:.1f} | {r['cruise_stall_margin_deg']:.1f} |")
w("")
w("Why so little: the Phase 2 blade was already optimised for this mission (two-point refinement over hover and cruise). A fixed-pitch rotor moves"
  " its operating point with RPM, which keeps the sections near their design lift coefficient, so pitch only buys the last ~1°. Pitching up does not"
  " raise T/W either: above 0° the U15XL hits its 180 A current limit before its RPM limit, and more pitch only makes each RPM cost more torque.\n")
w(f"**Control speed (hand calculation, not priced above).** Rotor inertia I ≈ 2 m R²/4 = {i_rot:.3f} kg·m² (2 blades of {ph1['mass_budget']['blade_kg']} kg, tapered)."
  f" Spare torque at hover = K_t I_peak − Q_hover = {kt:.3f} × {mot['peak_current_a']} − {q_h:.1f} = {dq:.1f} N·m (K_t = 60 / (2π KV))."
  f" +20 % thrust needs +9.5 % RPM (T ∝ Ω²), so Δt = I ΔΩ / ΔQ = {1000 * t_rpm:.0f} ms. That is quick for a large rotor, because the blades are light"
  " for their size. A pitch servo is still faster (~10–20 ms for a few degrees), and it can also give negative thrust. That matters for attitude"
  " authority in gusts, not for energy, so variable pitch is a controls question for later, not an efficiency one.\n")

w("## 3. Duct\n")
w("Momentum theory for a ducted rotor (disk area A, exit area σ_e A, disk velocity v_d):\n")
w("    T = ρ A v_d (v_d / σ_e)          →  v_d = √(σ_e T / (ρ A))")
w("    T_rotor / T = 1 / (2 σ_e)         (the inlet lip carries the rest by suction)")
w("    P_ideal = T^1.5 / √(4 σ_e ρ A)   vs  T^1.5 / √(2 ρ A) open  →  ratio 1 / √(2 σ_e) = 0.707 at σ_e = 1\n")
w(f"Hand check at the hover thrust {t_h:.0f} N per rotor: v_d = √({t_h:.0f} / ({rho:.3f} × {A:.3f})) = {vd_hand:.2f} m/s (code {duct0['v_d']:.2f});"
  f" open-rotor ideal {p_ideal_open:.0f} W for 3 rotors, ducted ideal {p_ideal_open / math.sqrt(2):.0f} W (code {duct0['P_ideal_w']:.0f}). The blade elements,"
  f" run with v_d prescribed and no tip loss, need {duct0['hover_w']:.0f} W ({100 * duct0['P_ideal_w'] / duct0['hover_w']:.0f} % of the ducted ideal), against"
  f" {b['hover_w']:.0f} W open: **{pct(duct0['hover_w'], b['hover_w']):.0f} %**. Keeping the open-rotor tip loss (a large tip gap) costs only"
  f" {duct0_tl['hover_w'] - duct0['hover_w']:.0f} W. A short diffuser (σ_e 1.1) gives {duct11['hover_w']:.0f} W. Real ducts lose some of this to"
  " inlet-lip separation, the diffuser and the tip gap, so the hover number is the upper bound of the benefit.\n")
w(f"**Cruise is where the duct loses.** Air reaches the duct horizontally at V and leaves along the duct axis, so the duct must remove its horizontal"
  f" momentum: momentum drag D = ṁ V = ρ A v_d V = {rho:.3f} × {A:.3f} × {vd_hand:.2f} × {p['mission']['cruise_speed_ms']:.0f} = {mom_hand:.0f} N per duct"
  f" (code {duct0['momentum_drag_n_each']:.0f}), about equal to its thrust. Add the ring's side drag ({duct0['ring_drag_n_each']:.0f} N, C_D {cs['duct']['ring_cd']} on D × L)"
  f" and the vehicle has to tilt far forward and push {duct0['cruise_w']['pessimistic_drag_n']:.0f} N of drag instead of {0.5 * rho * p['mission']['cruise_speed_ms'] ** 2 * p['vehicle']['cda_m2']:.0f} N."
  f" Bounds: induced power and disk velocity as in hover (pessimistic, {duct0['cruise_w']['pessimistic'] / 1000:.1f} kW), or dropping by the open rotor's own"
  f" hover-to-cruise ratio ({du['open_rotor_induced_ratio_cruise_over_hover']:.2f}, optimistic, {duct0['cruise_w']['optimistic'] / 1000:.1f} kW), against"
  f" {b['cruise_w'] / 1000:.1f} kW open. Even the optimistic bound doubles cruise power.\n")
w(f"Mass: a ring of length {cs['duct']['length_over_D']} D = {du['duct_length_m']:.2f} m, two skins at {cs['duct']['areal_density_kg_m2']} kg/m², plus"
  f" {100 * cs['duct']['struts_lip_fraction']:.0f} % for lip, stators and mounts: 2π D L × {cs['duct']['areal_density_kg_m2']} × {1 + cs['duct']['struts_lip_fraction']:.1f} = {du['duct_mass_kg_each']:.1f} kg each.\n")
w("A duct pays on a mission that is mostly hover (inspection, lifting at a site), not on a 10 nmi delivery run.\n")

w("## 4. Coaxial pair per arm (dual vertical offset)\n")
w("Two counter-rotating copies of the Phase 2 blade on each arm, offset vertically by h. Each wake is a semi-infinite vortex cylinder, which induces"
  " on its axis at distance z downstream (+) or upstream (−) of its disk:\n")
w("    w(z) = v_i (1 + z / √(R² + z²))        w(−z) = v_i (1 − z / √(R² + z²))")
w("    slipstream radius by continuity:  r_w = R √(v_i / w(z))   → R / √2 far downstream\n")
w("The lower rotor runs the Phase 2 BEMT with w(h) as extra inflow inside r_w and none outside. The upper rotor runs it with the lower rotor's upstream"
  " induction. Both are iterated to convergence and trimmed to the arm's thrust with **equal torque** (yaw balance).\n")
w("Interference factor κ_int = (induced + interference power of the pair) / (2 × induced power of one isolated rotor at T/2):\n")
w("| h / D | κ_int (equal torque) | κ_int (equal thrust) | Upper thrust share | RPM upper / lower | Arm hover power vs one rotor |")
w("|---|---|---|---|---|---|")
for r in cx["rows"]:
    w(f"| {r['h_over_D']} | {r['kappa_int']:.3f} | {r['kappa_int_equal_thrust']:.3f} | {r['split_upper']:.3f} | {r['rpm_upper']:.0f} / {r['rpm_lower']:.0f} | {100 * (r['vs_single_rotor'] - 1):+.1f} % |")
hc = cx["hand_check"]
w("")
w(f"Hand checks. (1) At h → 0 the two disks merge into one carrying twice the thrust, so κ_int → 2^1.5 / 2 = √2 = 1.414 (code at h/D 0.1: {cx['rows'][0]['kappa_int']:.3f})."
  f" (2) Far downstream the slipstream radius is R/√2 = {hc['r_wake_far_hand']:.4f} R (code {hc['r_wake_far_over_R']:.4f} R)."
  f" (3) Uniform loading, far spacing, equal thrust: the upper rotor is isolated (P = T v_h). The inner half of the lower rotor sees 2 v_h, so"
  f" 2ρ(2v_h + v)v = 2ρ v_h² → v = (√2 − 1) v_h, and its outer half has v = v_h. Then κ_int = [1 + (1 + √2 + 1)/2] / 2 = {hc['kappa_int_uniform_far_hand']:.3f}."
  f" The BEMT gives {hc['kappa_int_bemt_far']:.3f}, lower because the real blade carries most of its thrust outboard of 0.71 R, outside the upper wake."
  f" Leishman's momentum value is {hc['leishman_momentum_equal_thrust']} (different lower-wake assumption), and measured coaxial rotors fall in 1.16–1.3.\n")
w(f"So in hover the second rotor on each arm buys little: {100 * (1 - sel['vs_single_rotor']):.1f} % at h/D {G}, rising to {100 * (1 - cx['rows'][-1]['vs_single_rotor']):.0f} % at h/D 1.0 (a 1.4 m mast)."
  " The pair's blades also run at half load, below their design lift coefficient. A blade designed for the pair would do better.\n")
w(f"**Cruise.** Edgewise induced power goes as T² / (2 ρ A V), so it depends on how much fresh air each disk gets. Two isolated disks at T/2 would need half of"
  f" one disk's induced power. The upper wake skews back at χ = atan(μ/λ) = {c_['wake_skew_deg']:.0f}° from the shaft axis, so at the lower disk it has moved"
  f" d = h tan χ = {c_['wake_shift_m']:.2f} m aft, and covers a fraction f = {c_['overlap_fraction']:.2f} of the lower disk (overlap of two circles of radius R at centre"
  f" distance d). The estimate blends one-disk and isolated induced power by f: {c_['overlap_w'] / 1000:.1f} kW for the vehicle, between {c_['isolated_w'] / 1000:.1f} kW"
  f" (isolated) and {c_['one_disk_w'] / 1000:.1f} kW (one disk), against {b['cruise_w'] / 1000:.1f} kW open.\n")
w(f"Independent check (Prandtl biplane). A rotor in edgewise flight acts like a circular wing of span D, so a coaxial pair is a biplane with gap/span"
  f" G/b = {G}. Prandtl's interference factor σ = (1 − 0.66 G/b) / (1.055 + 3.7 G/b) = {sig_bi:.3f}, and for equal loads the pair's induced drag is"
  f" (1 + σ)/2 = {(1 + sig_bi) / 2:.3f} of one wing carrying both. The overlap model gives {ratio_overlap:.3f}. Vehicle cruise power by the biplane factor:"
  f" {cruise_biplane / 1000:.2f} kW, against {c_['overlap_w'] / 1000:.2f} kW.\n")
m = cs["masses"]
w(f"Mass per arm: single rotor {o['mass_refs']['arm_single_kg']:.2f} kg (U15XL {cat['motors']['tmotor_u15xl_kv38']['mass_kg']} kg + ESC + props + hub). A coaxial pair with half-power"
  f" motors (0.5 × U15XL × 1.15 for the smaller motor's lower power density) is {o['mass_refs']['arm_coax_scaled_kg']:.2f} kg. Cross-check: the Hobbywing H13 coaxial"
  f" pair is {o['mass_refs']['hobbywing_h13_pair_kg']} kg per arm with props, rated 45 kgf, max 113 kgf (our arm needs {t_h / 9.80665:.0f} kgf hover, {2 * t_h / 9.80665:.0f} kgf at T/W 2)."
  f" Removing the tricopter's yaw tilt mechanism saves an assumed {m['tilt_servo_kg']} kg.\n")
w(f"Motor-out: if one rotor of a pair fails, the other must lift the arm alone and the remaining arms trim the yaw. A full U15XL reaches"
  f" T/W {mo['six_u15xl_max_thrust_over_arm_hover']:.2f} on the arm's hover thrust, so it can. A half-size motor reaches {mo['half_size_max_thrust_over_arm_hover']:.2f}, so it cannot.\n")

w("## Vehicle summary\n")
w(f"| Configuration | Pack energy [Wh] (range) | vs baseline | Added hardware [kg] | Payload change [kg] at {WHKG:.0f} Wh/kg (range) | Note |")
w("|---|---|---|---|---|---|")
for s in S:
    rng = "" if abs(s["pack_wh_best"] - s["pack_wh_worst"]) < 1 else f" ({s['pack_wh_best']:.0f}–{s['pack_wh_worst']:.0f})"
    prng = "" if abs(s["pack_wh_best"] - s["pack_wh_worst"]) < 1 else f" ({pay(s['pack_wh_worst'], s['hardware_kg']):+.1f} to {pay(s['pack_wh_best'], s['hardware_kg']):+.1f})"
    w(f"| {s['config']} | {s['pack_wh_estimate']:.0f}{rng} | {pct(s['pack_wh_estimate'], b['pack_wh']):+.1f} % | {s['hardware_kg']:.1f} |"
      f" {pay(s['pack_wh_estimate'], s['hardware_kg']):+.1f}{prng} | {s['note']} |")
w("")
w("Payload change = −(added hardware + extra pack energy / pack specific energy), at fixed 280 lb MTOW (the Phase 1 decision).\n")
w("## Limits\n")
w("- The duct and coaxial cruise numbers come from simple wake models, bracketed rather than solved. Nothing here has been checked by CFD, and the"
  " Caradonna–Tung validation shows the CFD method still over-predicts torque by about 20 %.")
w("- The coaxial study reuses the Phase 2 blade at half load. A blade redesigned for the pair (lower solidity or lower RPM) is the next step.")
w("- The masses for pitch hubs, ducts and half-size motors are assumptions, listed in `params.yaml` under `config_study` with their sensitivities.")
w("- Coaxial spacing also changes the frame (mast height, landing-gear clearance, the lower rotor's ground effect). None of that is modelled.")
w("\nRegenerate: `python3 src/config_study.py` (about 3 minutes, one core), then `python3 make_config_report.py`.")
open(os.path.join(ROOT, "CONFIG_STUDY.md"), "w").write("\n".join(L) + "\n")
print("wrote CONFIG_STUDY.md")
